      --text: #172033;
      --muted: #5f6f89;
      --border: #d8e0ec;
      --accent: #2854d8;
      --accent-dark: #1f43ad;
      --accent-soft: #eef3ff;
      --error: #b42318;
      --success: #067647;
      --shadow: 0 24px 60px rgba(23, 32, 51, 0.12);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 2rem;
      background:
        radial-gradient(circle at top left, rgba(40, 84, 216, 0.16), transparent 30rem),
        var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
    }

    main {
      width: min(100%, 40rem);
    }

    .card {
      background: var(--card);
      border: 1px solid rgba(216, 224, 236, 0.8);
      border-radius: 1.5rem;
      box-shadow: var(--shadow);
      padding: clamp(1.5rem, 5vw, 3rem);
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      color: var(--accent);
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 6vw, 3rem);
      line-height: 1.1;
      letter-spacing: -0.04em;
    }

    .intro {
      margin: 1rem 0 2rem;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .form-field {
      margin: 0 0 1.5rem;
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      margin: 0 0 0.5rem;
      padding: 0;
      color: var(--text);
      font-size: 1.2rem;
      font-weight: 750;
    }

    .required-note,
    .field-help {
      color: var(--muted);
      font-size: 0.95rem;
    }

    .required-note {
      margin: 0 0 1rem;
    }

    .field-help {
      margin: 0 0 1rem;
    }

    .options {
      display: grid;
      gap: 0.75rem;
    }

    .radio-option {
      position: relative;
    }

    .radio-option input {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      margin: 0;
      opacity: 0;
      cursor: pointer;
    }

    .radio-option label {
      display: flex;
      align-items: center;
      gap: 0.875rem;
      min-height: 3.25rem;
      padding: 0.95rem 1rem;
      border: 1px solid var(--border);
      border-radius: 1rem;
      background: #fff;
      color: var(--text);
      font-weight: 650;
      transition: border-color 160ms ease, background-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
    }

    .radio-option label::before {
      content: "";
      flex: 0 0 1.25rem;
      width: 1.25rem;
      height: 1.25rem;
      border: 2px solid #7b8aa5;
      border-radius: 50%;
      background: #fff;
      box-shadow: inset 0 0 0 0.25rem #fff;
    }

    .radio-option input:hover + label {
      border-color: #8fa2c4;
      transform: translateY(-1px);
    }

    .radio-option input:checked + label {
      border-color: var(--accent);
      background: var(--accent-soft);
      box-shadow: 0 10px 28px rgba(40, 84, 216, 0.14);
    }

    .radio-option input:checked + label::before {
      border-color: var(--accent);
      background: var(--accent);
    }

    .radio-option input:focus-visible + label,
    button:focus-visible {
      outline: 3px solid #8cb4ff;
      outline-offset: 3px;
    }

    .error {
      margin: 0.9rem 0 0;
      color: var(--error);
      font-weight: 650;
    }

    button {
      width: 100%;
      border: 0;
      border-radius: 999px;
      background: var(--accent);
      color: #fff;
      cursor: pointer;
      font: inherit;
      font-weight: 750;
      padding: 0.95rem 1.25rem;
      transition: background-color 160ms ease, transform 160ms ease, box-shadow 160ms ease;
      box-shadow: 0 14px 26px rgba(40, 84, 216, 0.24);
    }

    button:hover {
      background: var(--accent-dark);
      transform: translateY(-1px);
    }

    .status {
      min-height: 1.5rem;
      margin: 1rem 0 0;
      color: var(--success);
      font-weight: 650;
    }

    [hidden] {
      display: none;
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
      }
    }

    @media (forced-colors: active) {
      .card,
      .radio-option label,
      button {
        border: 1px solid CanvasText;
        box-shadow: none;
      }

      .radio-option input:checked + label {
        forced-color-adjust: none;
        background: Highlight;
        color: HighlightText;
      }
    }
  </style>
</head>
<body>
  <main>
    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Account settings</p>
      <h1 id="page-title">Notification preferences</h1>
      <p class="intro">Choose the channel that works best for important product updates.</p>

      <form id="notification-form" novalidate>
        <p class="required-note"><span aria-hidden="true">*</span> Required field</p>

        <div class="form-field">
          <fieldset aria-describedby="notification-help notification-error">
            <legend>How do you prefer to receive notifications? <span aria-hidden="true">*</span></legend>
            <p id="notification-help" class="field-help">Select one notification method.</p>

            <div class="options">
              <div class="radio-option">
                <input id="notification-email" type="radio" name="notificationPreference" value="email" required>
                <label for="notification-email">Email</label>
              </div>

              <div class="radio-option">
                <input id="notification-sms" type="radio" name="notificationPreference" value="sms" required>
                <label for="notification-sms">SMS</label>
              </div>

              <div class="radio-option">
                <input id="notification-push" type="radio" name="notificationPreference" value="push" required>
                <label for="notification-push">Push Notifications</label>
              </div>
            </div>

            <p id="notification-error" class="error" hidden>Error: Choose one notification method.</p>
          </fieldset>
        </div>

        <button type="submit">Save preference</button>
        <p id="form-status" class="status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#notification-form");
    const radios = [...document.querySelectorAll('input[name="notificationPreference"]')];
    const error = document.querySelector("#notification-error");
    const status = document.querySelector("#form-status");

    function setError(isInvalid) {
      error.hidden = !isInvalid;
      radios.forEach((radio) => {
        radio.setAttribute("aria-invalid", String(isInvalid));
      });
    }

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selected = radios.find((radio) => radio.checked);

      if (!selected) {
        setError(true);
        status.textContent = "";
        radios[0].focus();
        return;
      }

      setError(false);
      status.textContent = `Preference saved: ${selected.labels[0].textContent}.`;
    });

    radios.forEach((radio) => {
      radio.addEventListener("change", () => {
        setError(false);
        status.textContent = "";
      });
    });
  </script>
</body>
</html>
